import {esc,fmt} from './offset-exports.js';
import {routeElbowFrame} from './offset-planner.js';

export const SCENE_VIEWS={iso:{label:'立體',axes:['run','rise'],matrix:[[.866,.866,0],[.5,-.5,-1]]},front:{label:'正視 XZ',axes:['run','rise'],matrix:[[1,0,0],[0,0,-1]]},top:{label:'俯視 XY',axes:['run','roll'],matrix:[[1,0,0],[0,-1,0]]},side:{label:'側視 YZ',axes:['roll','rise'],matrix:[[0,1,0],[0,0,-1]]}};
const xy=q=>q.map(v=>fmt(v)).join(' '),colors=['#b98335','#39846c','#3884a5'];
const project=(q,m)=>m.map(row=>row.reduce((s,v,i)=>s+v*q[i],0));
export function scenePoint(q,frame){return project(q,frame.matrix).map((v,i)=>frame.origin[i]+v*frame.scale);}
export function sceneDragDelta(delta,frame){const fields=frame.axes,idx=fields.map(f=>['run','roll','rise'].indexOf(f)),a=frame.matrix[0][idx[0]],b=frame.matrix[0][idx[1]],c=frame.matrix[1][idx[0]],d=frame.matrix[1][idx[1]],det=a*d-b*c;return {[fields[0]]:(d*delta[0]-b*delta[1])/det/frame.scale,[fields[1]]:(a*delta[1]-c*delta[0])/det/frame.scale};}
function frameFor(points,view,fixed){
  if(fixed)return fixed;const info=SCENE_VIEWS[view]??SCENE_VIEWS.iso,qs=points.map(q=>project(q,info.matrix)),min=[0,1].map(k=>Math.min(...qs.map(q=>q[k]))),max=[0,1].map(k=>Math.max(...qs.map(q=>q[k]))),scale=Math.min(340/Math.max(max[0]-min[0],160),205/Math.max(max[1]-min[1],160));
  return {...info,scale,origin:[300-(min[0]+max[0])/2*scale,213-(min[1]+max[1])/2*scale]};
}
function axisVector(p,end){const value=p[end+'Axis'];if(value==='custom'){const v=['X','Y','Z'].map(k=>Number(p[end+'Axis'+k])||0),n=Math.hypot(...v);return n?v.map(x=>x/n):[0,0,0];}const q=[0,0,0],i='xyz'.indexOf(value?.[0]);if(i>=0)q[i]=value[1]==='-'?-1:1;return q;}
const axisName=(p,end)=>p[end+'Axis']==='custom'?'斜向':p[end+'Axis']?.length===2?p[end+'Axis'][1]+p[end+'Axis'][0].toUpperCase():'未設定';
function compass(matrix,height){const start=[62,height-43];return `<g class="scene-compass"><text x="20" y="${height-90}">方向基準</text>${['X','Y','Z'].map((name,i)=>{const v=matrix.map(row=>row[i]),end=start.map((n,k)=>n+v[k]*29);return `<path d="M${xy(start)}L${xy(end)}" stroke="${colors[i]}" stroke-width="2"/><text x="${end[0]+(v[0]<0?-9:5)}" y="${end[1]+(v[1]<0?-6:12)}" fill="${colors[i]}">${name}</text>`;}).join('')}</g>`;}
function port(p,end,center,frame,selected,interactive=true){
 const pos=scenePoint(center,frame),v=project(axisVector(p,end),frame.matrix),n=Math.hypot(...v),u=n>1e-6?v.map(x=>x/n):[0,-1],tail=pos.map((x,i)=>x-u[i]*53),arrow=pos.map((x,i)=>x+u[i]*34),active=selected===end;
 return `<g class="scene-port${active?' selected':''}"${interactive?` data-port="${end}" role="button" tabindex="0" aria-label="${end.toUpperCase()} 管口朝 ${esc(axisName(p,end))}，點選朝向${end==='b'?'；拖曳調整位置':''}"`:''}><path d="M${xy(tail)}L${xy(pos)}" stroke="#4a6c76" stroke-width="29"/><path d="M${xy(tail)}L${xy(pos)}" stroke="${active?'#72baa6':'#b9d0d1'}" stroke-width="24"/><circle cx="${pos[0]}" cy="${pos[1]}" r="15" fill="#fff" stroke="${active?'#207761':'#4a6c76'}" stroke-width="3"/><circle cx="${pos[0]}" cy="${pos[1]}" r="32" fill="transparent"/><path d="M${xy(pos)}L${xy(arrow)}" stroke="#247461" stroke-width="2" marker-end="url(#measure-port-arrow)"/><g transform="translate(${pos[0]-52} ${pos[1]-75})"><rect width="104" height="43" rx="10" fill="${active?'#207761':'#fff'}" stroke="${active?'#207761':'#d6e3dc'}"/><text x="12" y="19" font-size="16" font-weight="600" fill="${active?'#fff':'#284e4d'}">${end.toUpperCase()} 口</text><text x="12" y="34" font-size="12" fill="${active?'#e5f8ed':'#657e75'}">朝 ${esc(axisName(p,end))}</text></g></g>`;
}
function svg(body,frame,label,height=380){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 ${height}" role="group" aria-label="${esc(label)}"><defs><marker id="measure-port-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#247461"/></marker></defs>${body}${compass(frame.matrix,height)}<text x="580" y="${height-16}" text-anchor="end" class="scene-scale-note">管口放大示意 · 尺寸依實測值</text></svg>`;}
export function portScene(p,view='iso',selected=null,fixed=null){
 const q=[p.run,p.layout==='rolling'?p.roll:0,p.rise].map(v=>Number.isFinite(v)?v:0),corners=[];for(const x of [0,q[0]])for(const y of [0,q[1]])for(const z of [0,q[2]])corners.push([x,y,z]);
 const frame=frameFor(corners,view,fixed),at=q=>scenePoint(q,frame),path=points=>points.map((q,i)=>(i?'L':'M')+xy(at(q))).join(' '),legs=[[0,0,0],[q[0],0,0],[q[0],q[1],0],q],edges=[];
 for(let i=0;i<8;i++)for(const bit of [1,2,4])if(!(i&bit))edges.push(`<path d="M${xy(at(corners[i]))}L${xy(at(corners[i|bit]))}"/>`);
 const ground=`<path d="${path([[0,0,0],[q[0],0,0],[q[0],q[1],0],[0,q[1],0]])}Z" fill="#e6f0e9" fill-opacity=".85"/>`;
 const dims=legs.slice(1).map((point,i)=>{const a=at(legs[i]),b=at(point),length=Math.hypot(b[0]-a[0],b[1]-a[1]);if(length<8)return '';const normal=[-(b[1]-a[1])/length,(b[0]-a[0])/length],mid=a.map((v,k)=>(v+b[k])/2+normal[k]*21);return `<g class="scene-dimension" data-dimension="${['run','roll','rise'][i]}" role="button" tabindex="0" aria-label="修改 ${['X','Y','Z'][i]} 距離 ${fmt(q[i])} 毫米"><path d="M${xy(a)}L${xy(b)}" stroke="${colors[i]}" stroke-width="2.8"/><circle cx="${a[0]}" cy="${a[1]}" r="3" fill="${colors[i]}"/><circle cx="${b[0]}" cy="${b[1]}" r="3" fill="${colors[i]}"/><rect x="${mid[0]-35}" y="${mid[1]-16}" width="70" height="32" rx="8" fill="#fff" stroke="#e0e9e3"/><text x="${mid[0]}" y="${mid[1]+5}" text-anchor="middle" fill="${colors[i]}" font-size="15">${['X','Y','Z'][i]}</text></g>`;}).join('');
 const body=`${ground}<g class="scene-construction" fill="none" stroke="#b8cbc4" stroke-dasharray="4 6">${edges.join('')}</g><path d="M${xy(at([0,0,0]))}L${xy(at(q))}" fill="none" stroke="#859f96" stroke-width="1.5" stroke-dasharray="7 7"/>${dims}${port(p,'a',[0,0,0],frame,selected)}${port(p,'b',q,frame,selected)}<text x="20" y="24" class="scene-basis-label">${p.datum==='marks'?'A 量測點 → B 量測點 · 標記修正另填':'A 端面中心 → B 端面中心'}</text>`;
 return {frame,svg:svg(body,frame,'兩管口的 XYZ 量測空間，彩色線為三軸距離')};
}
export function routeInputScene(plan,view='iso',selected=null,mode='gaps'){
 if(!plan?.valid||plan.legacy||!plan.context?.ports)return null;
 const curves=plan.elements.map(e=>e.type==='elbow'?[e.start,...Array.from({length:41},(_,i)=>routeElbowFrame(e,i/40).center),e.finish]:[e.start,e.finish]),points=curves.flat().concat(Object.values(plan.context.ports)),frame=frameFor(points,view),ys=points.map(q=>project(q,frame.matrix)[1]),extent=(Math.max(...ys)-Math.min(...ys))*frame.scale,height=Math.max(240,extent+165);
 frame.origin[1]=90-Math.min(...ys)*frame.scale;
 const at=q=>scenePoint(q,frame),parts=plan.elements.map((e,i)=>{
  const path=curves[i].map((q,j)=>(j?'L':'M')+xy(at(q))).join(' '),color=e.type==='component'?'#bb955e':e.type==='elbow'?'#70af9b':'#a7bec2';
  const mid=at(e.start.map((v,k)=>(v+e.finish[k])/2)),tag=e.type==='component'?`<text x="${mid[0]}" y="${mid[1]+36}" text-anchor="middle" font-size="14" fill="#966c36">${esc(e.id)} ${{valve:'閥組',flangePair:'法蘭組',custom:'零件'}[e.kind]??'零件'}</text>`:'';
  return `<path d="${path}" fill="none" stroke="#43666c" stroke-width="24" stroke-linejoin="round" stroke-linecap="round"/><path d="${path}" fill="none" stroke="${color}" stroke-width="18" stroke-linejoin="round" stroke-linecap="round"/>${tag}`;
 }).join('');
 const joints=mode==='gaps'?(plan.joints??[]).map(j=>{const q=at(j.start.map((v,k)=>(v+j.finish[k])/2)),active=j.id===selected;return `<g class="scene-route-joint${active?' selected':''}" data-input-joint="${esc(j.id)}" role="button" tabindex="0" aria-label="查看 ${esc(j.id)} ${j.kind==='bolt'?'螺栓接合':'焊口'}，預留 ${fmt(j.amount)} 毫米"><circle cx="${q[0]}" cy="${q[1]}" r="23" fill="transparent"/><circle cx="${q[0]}" cy="${q[1]}" r="${active?12:8}" fill="${active?'#b77a2b':'#fff'}" stroke="${j.kind==='bolt'?'#6582a7':'#b77a2b'}" stroke-width="3"/>${active?`<path d="M${q[0]} ${q[1]-13}V${q[1]-42}" stroke="#b77a2b"/><rect x="${q[0]-40}" y="${q[1]-73}" width="80" height="31" rx="8" fill="#fff" stroke="#cba16c"/><text x="${q[0]}" y="${q[1]-52}" text-anchor="middle" font-size="16" fill="#8b5b20">${esc(j.id)}</text>`:''}</g>`;}).join(''):plan.elbows.map(e=>{const q=at(routeElbowFrame(e,.5).center);return `<g><rect x="${q[0]-47}" y="${q[1]-52}" width="94" height="31" rx="8" fill="#fff" stroke="#9ac2ad"/><text x="${q[0]}" y="${q[1]-31}" text-anchor="middle" fill="#23634d" font-size="14">${esc(e.id)} · ${fmt(e.angle,1)}°</text></g>`;}).join('');
 const ports=['a','b'].map(end=>{const q=at(plan.context.ports[end]);return `<circle cx="${q[0]}" cy="${q[1]}" r="12" fill="#fff" stroke="#43666c" stroke-width="3"/><text x="${q[0]+(end==='a'?-20:20)}" y="${q[1]+6}" text-anchor="${end==='a'?'end':'start'}" font-size="17" font-weight="600" fill="#284e4d">${end.toUpperCase()} 口</text>`;}).join('');
 return {frame,svg:svg(`${parts}${ports}${joints}`,frame,`${plan.original?'原兩彎頭接法':'目前選用 '+(plan.id??'接法')}，${plan.jointCount} 個焊口，實際接合位置`,height)};
}
export function sceneReadouts(p){return `<div class="port-readouts">${[['run','X','前／後'],['roll','Y','左／右'],['rise','Z','上／下']].map(([key,axis,label],i)=>`<button type="button" data-dimension="${key}" style="--axis-color:${colors[i]}"${key==='roll'&&p.layout==='planar'?' disabled':''}><span>${axis} <small>${label}</small></span><strong>${fmt(key==='roll'&&p.layout==='planar'?0:p[key])}<small> mm</small></strong><i aria-hidden="true">↗</i></button>`).join('')}</div>`;}
